{
  "questions": {
    "multi_event_limit": {
      "hook": "route",
      "type": "probability",
      "instructions": "The request changes or sets a time, date, or limit for more than one event, or for an event and another person at the same time."
    },
    "ambiguous_reference": {
      "hook": "route",
      "type": "probability",
      "instructions": "The request names a person, event, or message that could match more than one item in the state, and the request does not add any extra detail that picks one."
    },
    "reply_scope": {
      "hook": "route",
      "type": "probability",
      "instructions": "The request asks to draft or edit a reply, and it asks to include more than one answer, or to answer everything, or to mention an additional fact beyond a single direct reply."
    },
    "consequence": {
      "hook": "tool",
      "type": "choice",
      "instructions": "What does this tool call change for people other than the user?",
      "criteria": {
        "none": "Only the user's own calendar or drafts",
        "other_event": "An event another person organized",
        "sends": "A message sent in the user's name"
      }
    },
    "reply_complete": {
      "hook": "output",
      "type": "probability",
      "instructions": "The reply answers every question the request asks."
    }
  },
  "rules": [
    {
      "question": "ambiguous_reference",
      "op": ">=",
      "action": "ask",
      "threshold": "ask"
    },
    {
      "question": "multi_event_limit",
      "op": ">=",
      "action": "deliberate",
      "threshold": "deliberate"
    },
    {
      "question": "reply_scope",
      "op": ">=",
      "action": "deliberate",
      "threshold": "deliberate"
    },
    {
      "question": "consequence",
      "op": "not_in",
      "action": "confirm",
      "value": [
        "none"
      ]
    },
    {
      "question": "reply_complete",
      "op": "<",
      "action": "revise",
      "threshold": "revise"
    }
  ]
}

